style.css:
[style*="/defects/wound/"]:after {
  font-size: 340%;
  letter-spacing: -5px;
  position: absolute;
  top: 0;
  right: 20%;
  background-color: #fff;
  border-radius: 10px;
  padding-right: 5px;
}

[style*="/defects/wound/2"]:after,
[style*="/defects/wound/3"]:after,
[style*="/defects/wound/4"]:after {
  color: #ff0000;
  filter: drop-shadow(0 0 2px currentColor);
}

[style*="/defects/wound/1"]:after {
  content: '!';
  color: #6e0606;
}

[style*="/defects/wound/2"]:after {
  content: '!!';
}

[style*="/defects/wound/3"]:after {
  content: '!!!';
}

[style*="/defects/wound/4"]:after {
  content: '!!!!';
}
